const DEFAULT_SKILLS_ROOT = "~/.buzz/SKILLS";

const ENTRY_LINE = (slug, description) => `- ${slug} — ${description}`;

function header(language, root) {
  if (language === "en") {
    return {
      open: "<plugin-instructions plugin=\"loop.skills\">",
      intro: `Approved procedures your owner has written or accepted live in ${root}.`,
      read: "Call skills_read with a slug before starting a task one of them covers.",
      empty: "No approved skills yet — the library is empty and that is fine.",
      draft:
        "If a task made you do something you would otherwise have to be told again, call skills_draft once to propose it. The owner decides; you cannot approve your own draft.",
    };
  }
  return {
    open: "<plugin-instructions plugin=\"loop.skills\">",
    intro: `승인된 절차는 ${root} 에 있습니다.`,
    read: "그 절차가 다루는 작업을 시작하기 전에 skills_read 로 slug 를 지정해 읽으세요.",
    empty: "아직 승인된 스킬이 없습니다. 라이브러리가 비어 있는 것이 정상입니다.",
    draft:
      "다시 설명받지 않아도 되게 만든 일이 있었다면 skills_draft 를 한 번 호출해 제안하세요. 승인은 소유자가 합니다. 자기 초안을 스스로 승인할 수는 없습니다.",
  };
}

const CLOSE = "</plugin-instructions>";

function draftOnly(language, root) {
  const t = header(language, root);
  if (language === "en") {
    return [
      t.open,
      t.intro,
      t.empty,
      `Call skills_list to check. It returns nothing until the owner approves a draft.`,
      t.draft,
      CLOSE,
    ].join("\n");
  }
  return [
    t.open,
    t.intro,
    t.empty,
    "확인하려면 skills_list 를 호출하세요. 소유자가 초안을 승인하기 전까지는 아무것도 나오지 않습니다.",
    t.draft,
    CLOSE,
  ].join("\n");
}

/** One description, cut at a character boundary, ending in an ellipsis. */
function cutDescription(description, maxChars) {
  const chars = [...description];
  if (chars.length <= maxChars) return description;
  return `${chars.slice(0, Math.max(0, maxChars - 1)).join("")}…`;
}

/**
 * @param entries readonly { slug, description, approvedAt }[], any order
 * @param options { language?: "ko" | "en", skillsRoot?: string }
 * @returns { text, included, dropped }
 */
function buildInjection(entries, options = {}) {
  const language = options?.language === "en" ? "en" : "ko";
  const root = typeof options?.skillsRoot === "string" && options.skillsRoot
    ? options.skillsRoot
    : DEFAULT_SKILLS_ROOT;

  const all = (Array.isArray(entries) ? entries : [])
    .filter((e) => e && typeof e.slug === "string" && e.slug)
    .map((e) => ({
      slug: e.slug,
      description: typeof e.description === "string" ? e.description.trim() : "",
      approvedAt: typeof e.approvedAt === "number" ? e.approvedAt : 0,
    }))
    .sort((a, b) => b.approvedAt - a.approvedAt || (a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0));

  // Zero approved skills is a complete product state, not a broken one — and it
  // is the ONLY moment the agent learns to draft, so this must never be "".
  if (all.length === 0) return { text: draftOnly(language, root), included: 0, dropped: 0 };

  const t = header(language, root);
  const head = [t.open, t.intro, "", t.read, ""];
  const list = language === "en"
    ? "Call skills_list to see this list again."
    : "이 목록을 다시 보려면 skills_list 를 호출하세요.";
  const tail = ["", list, t.draft, CLOSE];

  const render = (kept) => [...head, ...kept.map((e) => ENTRY_LINE(e.slug, e.description)), ...tail].join("\n");

  const kept = all.slice();
  let text = render(kept);

  // 1. Drop the oldest whole entries.
  while (utf8Length(text) > INJECT_LIMIT && kept.length > 0) {
    kept.pop();
    text = render(kept);
  }

  // 2. Still over? Trim the longest description, at a character boundary.
  while (utf8Length(text) > INJECT_LIMIT && kept.length > 0) {
    const longest = kept.reduce((a, b) => ([...b.description].length > [...a.description].length ? b : a));
    const chars = [...longest.description];
    if (chars.length <= 1) break;
    longest.description = cutDescription(longest.description, Math.max(1, Math.floor(chars.length / 2)));
    text = render(kept);
  }

  // 3. Last resort: header and footer alone are fixed cost, so the list goes.
  if (utf8Length(text) > INJECT_LIMIT) {
    kept.length = 0;
    text = draftOnly(language, root);
  }

  // Description cap belongs to the entry, not the budget, but enforcing it here
  // means one bad entry cannot push the block over.
  if (kept.some((e) => [...e.description].length > DESCRIPTION_MAX)) {
    for (const e of kept) e.description = cutDescription(e.description, DESCRIPTION_MAX);
    text = render(kept);
    if (utf8Length(text) > INJECT_LIMIT) { kept.length = 0; text = draftOnly(language, root); }
  }

  return { text, included: kept.length, dropped: all.length - kept.length };
}

// ---- src/inject.js ----
// Owns the single <plugin-instructions> block.
//
// Two constraints shape this, both from the host:
//   - `addInstructions` THROWS above 4096 UTF-8 bytes; it does not truncate.
//     `buildInjection` never exceeds it, but a failure here must still not reach
//     the agent's turn.
//   - A second registration of the same contribution id throws, and two
//     revisions of the plugin can be alive at once during a reload. So the
//     previous block is disposed *before* the next is registered, and an
//     identical text registers nothing at all.


class InjectionHolder {
  #register;
  #onError;
  #build;
  #text;
  #release;

  /**
   * @param register (text) => dispose — registers the block, returns its handle
   * @param onError (error) => void — called instead of throwing
   * @param build (entries, options) => { text } — injectable for the failure path
   */
  constructor(register, onError = () => {}, build = buildInjection) {
    this.#register = register;
    this.#onError = onError;
    this.#build = build;
    this.#text = undefined;
    this.#release = undefined;
  }

  /** Rebuild and, if the text changed, replace the live block. Never throws. */
  set(entries, options = {}) {
    let text;
    try {
      const result = this.#build(entries, options);
      text = typeof result === "string" ? result : result?.text;
      if (typeof text !== "string" || !text) throw new Error("injection text was empty");
    } catch (error) {
      // The previous block stays live; an agent keeps the procedures it had.
      this.#onError(error);
      return;
    }

    // The common case: a tool call that changed nothing worth re-registering.
    if (text === this.#text) return;

    const previous = this.#release;
    this.#release = undefined;
    // Dispose first: registering the same id twice throws, and the throw would
    // leave the plugin with neither block.
    if (previous) {
      try { previous(); } catch { /* already gone */ }
    }
    try {
      this.#release = this.#register(text);
      this.#text = text;
    } catch (error) {
      // The only way this throws is a *previous revision* of the plugin still
      // holding the id, which owns a scope this one cannot dispose. That block
      // is still delivering procedures, so keeping it is the right outcome:
      // agents lose nothing, and the host's normal reload order (dispose then
      // apply) never reaches this path. Verified in both orders.
      this.#text = undefined;
      this.#onError(error);
    }
  }

  /** Idempotent: removing a block that is not there is not an error. */
  dispose() {
    const release = this.#release;
    this.#release = undefined;
    this.#text = undefined;
    if (!release) return;
    try { release(); } catch { /* already gone */ }
  }
}

// ---- src/request.js ----
// How the plugin talks to its child process.
//
// Measured constraint, not a preference: Windows caps a whole process command
// line at 32767 characters, and a 32 KB ASCII draft body in argv already fails
// with ENAMETOOLONG. A draft body may be 60 KB. So the helper SOURCE travels in
// argv (`-e`) and the REQUEST travels on stdin.


/** `[--input-type=module, -e, <source>]` — the argv for `ctx.host.spawn`. */
function helperArgs() {
  return ["--input-type=module", "-e", HELPER_SOURCE];
}

/** The one line the helper reads from stdin. Never an argument. */
function helperRequest(command, payload = {}) {
  return JSON.stringify({ command, ...payload });
}

/**
 * The helper prints exactly one JSON object. A stray line must not be able to
 * fake success, so the LAST parseable object wins; anything unparseable is a
 * reported failure, never a throw into the agent's turn.
 */
function parseReply(stdout) {
  const text = String(stdout ?? "").trim();
  if (!text) return { ok: false, error: "helper printed no result" };
  const lines = text.split("\n");
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const line = lines[i].trim();
    if (!line.startsWith("{")) continue;
    try {
      const value = JSON.parse(line);
      if (value && typeof value === "object" && typeof value.ok === "boolean") return value;
    } catch {
      // keep looking further back
    }
  }
  return { ok: false, error: "helper printed no result" };
}

// ---- src/tools.js ----
// The three tools an agent can call. Every failure is a sentence the agent can
// act on — nothing here throws into a turn, because a thrown tool error ends the
// agent's work rather than teaching it.


const slug = {
  type: "string",
  minLength: 1,
  maxLength: SLUG_MAX,
  pattern: "^[a-z0-9][a-z0-9._-]*$",
};

const TOOLS = [
  {
    name: "skills_list",
    description:
      "List the procedures the owner has approved. Returns one slug and one line each. Call skills_read before doing a task one of them covers.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
  },
  {
    name: "skills_read",
    description:
      "Read one approved procedure in full by slug. Drafts are not readable until the owner approves them.",
    inputSchema: {
      type: "object",
      properties: { slug },
      required: ["slug"],
      additionalProperties: false,
    },
  },
  {
    name: "skills_draft",
    description:
      "Propose a repeatable procedure for the owner to review. Use it once when a task taught you something you would otherwise have to be told again. The draft is not visible to any agent until the owner approves it.",
    inputSchema: {
      type: "object",
      properties: {
        slug: { ...slug, description: "Short kebab-case id, e.g. weekly-sales-report" },
        name: { type: "string", minLength: 1, maxLength: 80 },
        description: { type: "string", minLength: 1, maxLength: DESCRIPTION_MAX, description: "One line saying when to use it" },
        body: { type: "string", minLength: 1, maxLength: 61440, description: "The procedure, in markdown" },
        why: { type: "string", minLength: 1, maxLength: 400, description: "One line: what would have to be re-explained next time" },
      },
      required: ["slug", "name", "description", "body", "why"],
      additionalProperties: false,
    },
  },
];

/** One `spawn` call, with a timeout so a hung helper does not hold the turn. */
async function send(deps, command, payload) {
  const timeoutMs = deps.timeoutMs ?? 20_000;
  let timer;
  try {
    // A spawn failure is a normal outcome (no desktop, no permission), so it is
    // converted here rather than escaping to the outer catch, which would report
    // it without the sentence the agent needs.
    const work = (async () => {
      try {
        const result = await deps.spawn(command, payload);
        return parseReply(result?.stdout);
      } catch (error) {
        return { ok: false, error: String(error?.message ?? error) };
      }
    })();
    const timeout = new Promise((resolve) => {
      timer = setTimeout(() => resolve({ ok: false, error: `the ${command} step did not finish in time` }), timeoutMs);
    });
    return await Promise.race([work, timeout]);
  } finally {
    // The timer outlives the call otherwise, which keeps the plugin's process
    // graph alive for 20 s after every single tool call.
    clearTimeout(timer);
  }
}

function approvedList(skills) {
  return (Array.isArray(skills) ? skills : [])
    .filter((s) => s && s.state === "approved")
    .sort((a, b) => String(b.approvedAt ?? "").localeCompare(String(a.approvedAt ?? "")));
}

const failureSentence = (reply, command) => {
  const error = String(reply?.error ?? "");
  if (/desktop|not available|unsupported/i.test(error)) {
    return `I couldn't write to the skills folder: ${error}. Procedures need the desktop app.`;
  }
  if (/absolute/i.test(error)) return `I couldn't write to the skills folder: ${error}.`;
  return `I couldn't ${command}: ${error || "the helper returned nothing"}`;
};

/**
 * @param deps { spawn: (command, payload) => Promise<{stdout}>, root: string, notifyDraft?: Function, timeoutMs?: number }
 * @returns a sentence for the agent. Never throws.
 */
async function callTool(deps, name, args = {}, context = {}) {
  try {
    if (name === "skills_list") {
      const reply = await send(deps, "list", { root: deps.root });
      if (!reply.ok) return failureSentence(reply, "read the list of skills");
      const approved = approvedList(reply.data?.skills);
      if (approved.length === 0) {
        return "No approved skills yet. If this task taught you something repeatable, call skills_draft once to propose it.";
      }
      const lines = approved.map((s) => `- ${s.slug} — ${s.description || s.name || s.slug}`);
      return ["Approved skills:", ...lines, "", "Call skills_read with a slug before doing a task one of them covers."].join("\n");
    }

    if (name === "skills_read") {
      if (typeof args.slug !== "string" || !args.slug) return "I need a slug to read. Call skills_list first.";
      const reply = await send(deps, "read", { root: deps.root, slug: args.slug });
      if (!reply.ok) {
        return `"${args.slug}" is not readable until the owner approves it. Use skills_list to see what is approved.`;
      }
      const body = String(reply.data?.body ?? reply.data?.text ?? "");
      return body || `"${args.slug}" has no body yet.`;
    }

    if (name === "skills_draft") {
      // Checked here, before the disk, so a bad argument costs nothing and the
      // agent gets the number it violated rather than a helper-internal error.
      const description = String(args.description ?? "");
      if ([...description].length > DESCRIPTION_MAX) {
        return `The description must be at most ${DESCRIPTION_MAX} characters; this one is ${[...description].length}. Shorten it to one line and try again.`;
      }
      const reply = await send(deps, "draft", {
        root: deps.root,
        slug: args.slug,
        name: args.name,
        description,
        body: args.body,
        why: args.why,
        channel: context.channel ?? "",
        agent: context.agent ?? context.session ?? "agent",
      });
      if (!reply.ok) {
        if (reply.error === "pending") {
          return `A draft for "${args.slug}" is already waiting for the owner. Do not draft it again.`;
        }
        if (reply.error === "rejected") {
          return `The owner rejected an earlier draft of "${args.slug}"${reply.reason ? `: ${reply.reason}` : "."} Do not resubmit it unchanged; act on the reason.`;
        }
        if (reply.error === "already-approved") {
          return `"${args.slug}" is already an approved skill. Read it instead of drafting it.`;
        }
        return failureSentence(reply, "save the draft");
      }
      if (typeof deps.notifyDraft === "function") {
        try { await deps.notifyDraft({ slug: args.slug, name: args.name }); } catch { /* a missed notification is not a failed draft */ }
      }
      return `Draft saved and waiting for the owner to review it: ${args.slug}. It is not visible to any agent until they approve it, so keep working without it.`;
    }

    return `Unknown tool: ${name}`;
  } catch (error) {
    return `That did not work: ${String(error?.message ?? error)}`;
  }
}

/** The one line the plugin sends per call; kept here so the spawn wiring is tiny. */
const requestFor = helperRequest;

// ---- src/plugin.js ----
// Registration only. Everything else is a module above; see scripts/build.mjs.
//
// The host loads this module from a blob URL, so it must not import anything and
// must not do work at top level. `inject` is a module export, not a call.
//
// What this registers:
//   - three agent tools (skills_list, skills_read, skills_draft)
//   - one <plugin-instructions> block, kept under the host's 4096-byte cap
//   - a settings card that is the library humans approve from
//   - one notification, so a draft arrives quietly instead of as a banner
//
// It registers no agent tab in v1: that surface is not on the documented steady
// set, and the settings card is canonical. A tab is a later convenience.

export const inject = ["agents", "settingsCards", "notifications", "host"];

const SKILLS_ROOT = "~/.buzz/SKILLS";

/**
 * The spawn the tools use. The request travels on stdin, never in argv: Windows
 * caps a whole command line at 32767 characters and a draft body may be 60 KB.
 */
function makeSpawn(ctx, timeoutMs = 20_000) {
  return async (command, payload) => {
    const child = await ctx.host.spawn("skills", { args: helperArgs() });
    let stdout = "";
    child.onStdout?.((data) => { stdout += data; });
    const collected = new Promise((resolve) => {
      child.exited.then(() => resolve(stdout)).catch(() => resolve(stdout));
    });
    let timer;
    try {
      await child.write(helperRequest(command, payload));
      await child.end();
      const timedOut = new Promise((resolve) => {
        timer = setTimeout(() => resolve(stdout), timeoutMs);
      });
      return { stdout: String(await Promise.race([collected, timedOut]) ?? "") };
    } finally {
      // An uncleared timer holds the process graph open for 20 s after every
      // call, which is visible as a test run that takes 20 s per tool test.
      clearTimeout(timer);
    }
  };
}

export function apply(ctx) {
  let root;
  let rootFailed;
  const rootReady = (async () => {
    try {
      root = await ctx.host.resolveDirectory(SKILLS_ROOT, { create: true });
    } catch (error) {
      // Without a root every tool still answers with a sentence, so a missing
      // folder is a degraded plugin, not a broken one.
      rootFailed = String(error?.message ?? error);
    }
    return root;
  })();

  const spawn = makeSpawn(ctx);

  let notifyDraft = async () => {};
  try {
    const draftNotification = ctx.notifications.register({ id: "draft", label: "Skill draft" });
    const announced = new Set();
    notifyDraft = async ({ slug, name }) => {
      if (announced.has(slug)) return;
      announced.add(slug);
      await draftNotification.submit({
        sourceKey: slug,
        target: { version: 1, kind: "plugin", pluginId: "loop.skills", pageId: "library" },
        title: "스킬 초안",
        body: String(name ?? slug),
      });
    };
  } catch {
    // No notifications on this surface; drafting still works.
  }

  const deps = () => ({ spawn, root: root ?? "", notifyDraft, timeoutMs: 20_000 });

  // Owns the <plugin-instructions> block. A child scope is used because
  // addInstructions has no removal handle of its own, and registering the same
  // id twice throws — so replacing the block means disposing the scope.
  const holder = new InjectionHolder(
    (text) => {
      const scope = ctx.plugin({
        inject: ["agents"],
        apply: (child) => child.agents.addInstructions({ id: "skills-index", text }),
      });
      return () => scope.dispose();
    },
    (error) => console.warn("loop.skills: could not update the skills block", error),
  );
  const refresh = async () => {
    try {
      if (!(await rootReady) || !root) return;
      const reply = parseReply((await spawn("list", { root })).stdout);
      if (!reply.ok) return;
      const entries = (reply.data?.skills ?? [])
        .filter((s) => s.state === "approved")
        .map((s) => ({
          slug: s.slug,
          description: s.description,
          approvedAt: Date.parse(s.approvedAt) || 0,
        }));
      holder.set(entries, { language: "ko", skillsRoot: root });
    } catch {
      // A failed refresh must not kill a turn, and the previous block stays
      // live. This is the normal state with no desktop host, so it is not
      // logged: a warning per turn is noise, not information.
    }
  };

  ctx.effect(() => () => holder.dispose());

  for (const tool of TOOLS) {
    ctx.agents.addTool({
      name: tool.name,
      description: tool.description,
      inputSchema: tool.inputSchema,
      call: async (_client, context, args) => {
        await rootReady;
        if (!root) {
          return `I can't reach the skills folder (${rootFailed ?? "it did not resolve"}). Procedures need the desktop app.`;
        }
        const reply = await callTool(deps(), tool.name, args ?? {}, context ?? {});
        // A draft changes nothing an agent can see, but a decision does; refresh
        // after every call so an approval takes effect on the next turn.
        void refresh();
        return reply;
      },
    });
  }

  // The zero-skill block must be live from the very first turn, not after the
  // first draft: it is the only thing that tells an agent drafting exists.
  void refresh();
}
